async function festivalSay(){
 if(!festivalGame||festivalGame.completed)return;
 const text=festivalGame.instruction.join('。'),game=festivalGame,token=++epoch;
 speechPlayer.cancel();sounds.stop();
 const ok=await speechPlayer.play(text,{lang:'zh-TW',clip:festivalAudio.audio[text],level:settings.speed,selection:settings.zhVoice});
 if(!ok&&token===epoch&&page==='festival-game'&&game===festivalGame){const el=document.querySelector('#festival-audio-status');if(el)el.textContent='玩法語音暫時不能播放，仍可依畫面提示繼續遊戲。';}
}
function openFestival(id){
 const event=festivalEvents(festivalCatalog,festivalYear).find(e=>e.id===id);if(!event)return;
 stop();paused=false;document.body.classList.remove('paused');page='festival-game';
 festivalGame=new FestivalGame({event,year:festivalYear,render,active:()=>page==='festival-game'&&!paused,effect:kind=>sounds.festival(kind),complete:result=>{
  const key=`${result.year}/${result.id}`;festivalRecords[key]={count:(festivalRecords[key]?.count||0)+1,date:new Date().toISOString()};persist();sounds.dance(4);
 }});render();window.scrollTo?.(0,0);
}
