async function lifeSpeak(parts){const key=JSON.stringify(parts);if(parts.length&&speechPlayer.pending&&key===lifeNarrationKey)return;lifeNarrationKey=key;speechPlayer.cancel();const token=++epoch;for(const part of parts){if(token!==epoch||page!=='life-game'||document.hidden)return;const ok=await speechPlayer.play(part.text,{lang:part.lang,clip:part.clip,level:settings.speed,selection:part.lang==='ja-JP'?settings.jaVoice:settings.enVoice});if(token!==epoch)return;if(!ok){const el=document.querySelector('.life-audio');if(el)el.textContent='語音暫時不能播放，可以看文字、選圖片繼續。';return;}}}
function visitDestination(id){if(schoolGate.locked&&id!=='school')return;if(blockVenue(WorldTime.venueForDestination(id)))return;if(id==='town-salon'){salonVisit??=new Salon.SalonVisit();selectedScene=id;go('salon');return;}if(['town-department','town-department-market','town-department-bakery'].includes(id)){departmentVisit??=new Department.DepartmentVisit(Department.departmentCatalog(catalog));departmentVisit.selectRoom(id==='town-department'?'lobby':id.endsWith('-market')?'market':'bakery');selectedScene=id;go('department-store');return;}if(['town-hospital','town-hospital-dental','town-hospital-ent'].includes(id)){hospitalVisit??=new Hospital.HospitalVisit(Hospital.hospitalParts(catalog));hospitalVisit.selectRoom(id==='town-hospital'?'lobby':id.endsWith('-dental')?'dental':'ent');selectedScene=id;go('hospital');return;}if(id==='town-amusement'){selectedScene=id;go('amusement');return;}if(id==='town'){go('town');return;}if(id==='festival'){go('festivals');return;}if(id==='world'){go('world');return;}if(id==='school'){schoolLanguage='';lessonOrigin='school-books';go('school-books');return;}selectedScene=id;go('scene');}
