try{const manifest=await fetch(contentURL('./content/index.json')).then(r=>{if(!r.ok)throw Error('manifest');return r.json();});catalog=await Promise.all(manifest.books.map(async file=>{const r=await fetch(contentURL('./content/'+file));if(!r.ok)throw Error('content');return r.json();}));schoolStories=await fetch(contentURL('./content/school-stories.json')).then(r=>{if(!r.ok)throw Error('stories');return r.json();});parkMemories=await fetch(contentURL('./content/park-memories.json')).then(r=>{if(!r.ok)throw Error('memories');return r.json();}).catch(()=>({photos:[]}));sceneMemories=await fetch(contentURL('./content/scene-memories.json')).then(r=>{if(!r.ok)throw Error('scene memories');return r.json();}).catch(()=>({albums:{}}));festivalAudio=await fetch(contentURL('./content/festival-audio.json')).then(r=>{if(!r.ok)throw Error('festival audio');return r.json();});festivalCatalog=await fetch(contentURL('./content/festivals.json')).then(r=>{if(!r.ok)throw Error('festivals');return r.json();});hospitalAudio=await fetch(contentURL('./content/hospital-audio.json')).then(r=>{if(!r.ok)throw Error('hospital audio');return r.json();}).catch(()=>({audio:{}}));departmentAudio=await fetch(contentURL('./content/department-audio.json')).then(r=>{if(!r.ok)throw Error('department audio');return r.json();}).catch(()=>({audio:{}}));salonAudio=await fetch(contentURL('./content/salon-audio.json')).then(r=>{if(!r.ok)throw Error('salon audio');return r.json();}).catch(()=>({audio:{}}));catalog.sort((a,b)=>a.order-b.order);book=catalog[0];unit=book.units.find(u=>u.status==='ready');catalog.forEach(b=>b.units.filter(u=>u.status==='ready').forEach(u=>u.words.forEach(w=>u.language==='ja-JP'?japaneseArt(w.id):illustration(w.id))));render();worldClock.start();}catch{wrap('<div class="error"><h1>教材或音檔載入失敗</h1><p>請確認本機伺服器已啟動，再重新載入。</p><button onclick="location.reload()">重新載入</button></div>');}

function toolStatus(text,id='parent-tool-status'){const el=document.querySelector('#'+id);if(el)el.textContent=text;}
function bindParentTools(){
 backupRead++;pendingBackup=null;
 if(backupUndo)document.querySelector('#backup-preview').innerHTML=backupUndoHTML();
 document.querySelector('#only-learned').onchange=e=>{extras.onlyLearned=e.target.checked;saveExtras();};
 document.querySelector('#rest-minutes').onchange=e=>{extras.restMinutes=Number(e.target.value);restClock.reset();document.querySelector('#rest-reminder')?.remove?.();saveExtras();};
 const form=document.querySelector('#memory-note-form');const update=()=>{const photo=allMemoryPhotos().find(p=>p.id===form.elements.photo.value);if(photo){form.elements.date.value=photo.date||'';form.elements.caption.value=photo.caption||'';}};
 if(form.elements){form.elements.photo.onchange=update;update();}
 document.querySelector('#backup-file').onchange=async e=>{const revision=++backupRead;pendingBackup=null;const box=document.querySelector('#backup-preview'),file=e.target.files?.[0];if(!file)return;try{if(file.size>2000000)throw Error('備份檔太大。');const candidate=ParentTools.validateBackup(await file.text());if(page!=='settings'||revision!==backupRead)return;pendingBackup=candidate;const data=candidate.data;box.innerHTML=`<p>備份包含 ${Object.keys(data['nickson-records']||{}).length} 個單元、${Object.keys(data['panda-school-extras']?.notes||{}).length} 則照片故事。還原會取代目前紀錄，完成後可復原。</p><button data-parent-tool="restore">確認還原這份備份</button><button data-parent-tool="cancel">取消</button>`;}catch(error){if(page==='settings'&&revision===backupRead)box.textContent=error.message;}};
}
function parentToolSubmit(form){
 if(page!=='settings')return;
 if(form.id==='change-pin-form'){const fields=form.elements;if(fields.next.value!==fields.repeat.value){toolStatus('兩次新密碼不一致。','pin-status');return;}const ok=schoolGate.changePassword(fields.current.value,fields.next.value);toolStatus(ok?'解鎖密碼已更新。':'目前密碼不正確、新密碼不是六位數，或瀏覽器無法儲存。','pin-status');if(ok)form.reset();return;}
 const photo=allMemoryPhotos().find(p=>p.id===form.elements.photo.value),date=form.elements.date.value,caption=form.elements.caption.value.trim();if(!photo||!ParentTools.validDate(date))return;extras.notes[photo.id]={date,caption};saveExtras();toolStatus(storageOK?'照片的小故事已儲存。':'瀏覽器無法保存，請先下載備份。','memory-note-status');
}
function parentToolAction(action){
 if(page!=='settings')return;
 try{
 if(action==='export'){persist();saveExtras();const blob=new Blob([JSON.stringify(ParentTools.backupSnapshot(localStorage),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='panda-school-'+new Date().toISOString().slice(0,10)+'.json';a.hidden=true;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toolStatus('備份已下載，請保存檔案。');}
 if(action==='cancel'){backupRead++;pendingBackup=null;document.querySelector('#backup-preview').innerHTML='';}
 if(action==='restore'&&pendingBackup){backupUndo=ParentTools.restoreBackup(localStorage,pendingBackup);pendingBackup=null;reloadParentData();render();revealBackupTools();}
 if(action==='undo'&&backupUndo){const data={};for(const [key,value]of backupUndo)if(value!==null)data[key]=JSON.parse(value);ParentTools.restoreBackup(localStorage,{data});backupUndo=null;reloadParentData();render();revealBackupTools();toolStatus('已回到還原前的紀錄。');}
 }catch(error){toolStatus('未完成操作，原有紀錄保留。請確認瀏覽器允許儲存。');}
}
function backupUndoHTML(){return '<p>本次已還原備份，可回到還原前；重新整理後將結束復原機會。</p><button data-parent-tool="undo">復原這次還原</button>';}
function revealBackupTools(){const section=document.querySelector('#parent-backup');if(section)section.open=true;document.querySelector('[data-parent-tool="undo"]')?.focus?.({preventScroll:true});section?.scrollIntoView?.({block:'nearest'});}
function reloadParentData(){settings={options:2,music:true,ambient:false,motion:true,speechVolume:100,effectsVolume:100,ambientVolume:100,speed:3,enVoice:'auto',zhVoice:'auto',jaVoice:'auto',...JSON.parse(localStorage.getItem('nickson-settings')||'{}')};records=JSON.parse(localStorage.getItem('nickson-records')||'{}');festivalRecords=JSON.parse(localStorage.getItem('nickson-festivals')||'{}');Object.assign(extras,ParentTools.loadExtras(localStorage));applyVolumes();restClock.reset();document.querySelector('#rest-reminder')?.remove?.();}
function startRestReminder(){if(restTimer!==null||typeof window.setInterval!=='function')return;restTimer=window.setInterval(()=>{if(restClock.tick(Date.now(),!document.hidden,extras.restMinutes)&&!document.querySelector('#rest-reminder')){const note=document.createElement('aside');note.id='rest-reminder';note.className='rest-reminder';note.setAttribute('role','status');note.innerHTML='<span>🌿 眼睛休息一下，看看遠方、喝口水吧。遊戲會留在這裡。</span><button>好，知道了</button>';note.querySelector('button').onclick=()=>{restClock.reset();note.remove();};document.body.append(note);}},1000);document.addEventListener('visibilitychange',()=>{restClock.tick(Date.now(),false,extras.restMinutes);});}
function openMemoryZoom(){const photos=memoryAlbum(sceneMemories,memoryScene,parkMemories,extras.notes).photos;if(!photos.length||page!=='park-memories')return;document.querySelector('#memory-zoom-dialog')?.remove?.();const dialog=document.createElement('dialog');dialog.id='memory-zoom-dialog';dialog.className='memory-zoom-dialog';dialog.setAttribute('aria-label','放大回憶照片');app.append(dialog);let start=null;const paint=()=>{const p=photos[memoryIndex];dialog.innerHTML=`<button data-zoom-close aria-label="關閉放大照片">✕ 關閉</button><img src="${escape(p.src)}" alt="${escape(p.alt)}" draggable="false"><p>${escape(p.title)} · ${memoryIndex+1} / ${photos.length}</p><details class="zoom-story"><summary>照片的小故事${p.date?' · '+escape(p.date):''}</summary><p>${escape(p.caption)}</p></details><div><button data-zoom-step="-1" ${memoryIndex===0?'disabled':''}>← 上一張</button><button data-zoom-step="1" ${memoryIndex===photos.length-1?'disabled':''}>下一張 →</button></div>`;};const close=()=>{dialog.close();dialog.remove();render();document.querySelector('[data-memory-zoom]')?.focus?.();};const step=n=>{memoryIndex=Math.max(0,Math.min(photos.length-1,memoryIndex+n));paint();const same=dialog.querySelector(`[data-zoom-step="${n}"]:not([disabled])`)||dialog.querySelector('[data-zoom-close]');same.focus({preventScroll:true});};dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.hasAttribute('data-zoom-close'))close();else if(b?.dataset.zoomStep)step(Number(b.dataset.zoomStep));});dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();step(e.key==='ArrowLeft'?-1:1);}});dialog.addEventListener('pointerdown',e=>{if(e.target.tagName==='IMG')start={x:e.clientX,y:e.clientY,id:e.pointerId};});dialog.addEventListener('pointercancel',()=>start=null);dialog.addEventListener('pointerup',e=>{if(start&&start.id===e.pointerId){const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy)*1.5)step(dx<0?1:-1);}start=null;});paint();dialog.showModal();}

function blockVenue(id,time=sceneTime()){
 if(!id||WorldTime.venueOpen(id,{...time,allScenesOpen}))return false;
 closedVenue=id;go('venue-closed');return true;
}
function blockClosedCurrent(time=sceneTime()){return blockVenue(WorldTime.venueForPage(page,selectedScene,lifePlace),time);}
function worldTimeChanged(time){
 if(!catalog.length)return;
 if(blockClosedCurrent(time))return;
 const shell=app.querySelector?.('.shell');if(shell){for(const phase of ['morning','day','sunset','night'])shell.classList.remove('world-phase-'+phase);shell.classList.add('world-phase-'+time.phase);}
 app.querySelectorAll?.('.world-time-badge').forEach(el=>{el.outerHTML=WorldTime.timeBadgeHTML(time);});
 if(['home','town','venue-closed'].includes(page))render();
}
app.addEventListener('pointerdown',event=>{if(blockClosedCurrent()){event.preventDefault?.();event.stopImmediatePropagation?.();}},{capture:true});
